import{z as n,x as s,o as l,c as o,q as E,j as t,D as e,d as r,s as A,S as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"结算周期与失败","description":"","frontmatter":{"title":"结算周期与失败","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/settlement-fails.md","filePath":"quant/settlement-fails.md","lastUpdated":1791063341000}'),d={name:"quant/settlement-fails.md"};function f(p,a,C,h,m,T){const i=s("Mermaid");return l(),o("div",null,[a[2]||(a[2]=E('<h1 id="结算周期与失败" tabindex="-1">结算周期与失败 <a class="header-anchor" href="#结算周期与失败" aria-label="Permalink to &quot;结算周期与失败&quot;">​</a></h1><div class="epigraph"><p>撮合确认的是契约，结算完成的是证券与资金的终局交付。周期缩短压缩对手方窗口，也压缩修复匹配错误的时间；失败交收于是从后台例外变成策略状态。</p><footer>—— Fleming and Garbade, Explaining Settlement Fails, FRBNY Current Issues, 2005；DTCC 关于失败交收与 T+1 的公开材料；SEC Rule 15c6-1 采用公告</footer></div><p><a href="/quant/ccp-default-waterfall">上一课</a>把信用停在 CCP 瀑布。<a href="/quant/us-t1-settlement">美国 T+1</a> 已写美股法定周期。<a href="/quant/cn-tplus1">A 股 T+1</a> 写的是交易侧不可回转。本课的缺口是<strong>交收周期与失败（fail）作为一般机制</strong>：国债、股票、跨境、以及「契约日 ≠ 资金日」时策略库存如何分列。后课借券与回购是 fail 的常见解药与来源。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记成交日 \\(T\\)，标准交收日 \\(S(T)\\)。在 \\(T\\) 与 \\(S(T)\\) 之间，市场风险已在，法定所有权未移。失败交收指 \\(S(T)\\) 未能完成券或款的交付。Fleming 与 Garbade（2005）说明美国国债 fail 在某些时期可以很高：券被锁在空头链或运营卡顿里，罚金若低于融资收益，fail 会被「理性地」维持——直到监管与市场惯例提高罚金。问题是把 fail 写成随机状态：确认未完成、券源不足、外汇未备妥、对手运营错误，各有不同的可预测性与成本。</p><p>周期从 T+3 到 T+2 再到 T+1，修复窗口消失。匹配错误从前一天可修，变成直接 fail。量化若只在日终持仓上记账，永远看不见 fail：纸面仓位已经「有了」。必须有交收状态机：<code>traded / matched / affirmed / settled / failed</code>。A 股股票的交易限制与结算周期叠在一起，但 fail 的会计仍独立：即使可卖量按交易规则锁定，结算失败也会打乱会员备付。</p><p><span class="marginnote">术语翻译：这串状态码是说——traded 只是双方约定；matched 是两边明细对上了；affirmed 是机构客户确认分配；settled 才是券钱真正换手；failed 是约定日没换成。回测若只看第一档和倒数第二档，中间的坑全部隐形。</span></p><h3 id="券-fail-与款-fail-不对称" tabindex="-1">券 fail 与款 fail 不对称 <a class="header-anchor" href="#券-fail-与款-fail-不对称" aria-label="Permalink to &quot;券 fail 与款 fail 不对称&quot;">​</a></h3><p>缺券时，买方资金可能被保护，卖方要去借券或买单。缺款时，融资与外汇管道被压。国债市场的 fail 常是缺券；跨境股票常是确认与外汇。ETF 申赎把成分券 fail 放大成篮子 fail。回测应分类型计价：借券费、罚金、强制补进的冲击、以及延迟到账导致的再投资缺口。</p>',9)),(l(),t(B,null,{default:e(()=>[A(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E4%BA%A4%E6%94%B6%E6%97%A5%20S(T)%20%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20Q%7B%22%E7%BC%BA%E7%9A%84%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20Q%20--%3E%7C%E7%BC%BA%E5%88%B8%7C%20SEC%5B%22%E5%88%B8%20fail%3A%20%E5%9B%BD%E5%80%BA%E4%B8%8E%E6%8C%A4%E7%A9%BA%E9%93%BE%E7%9A%84%E5%B8%B8%E8%A7%81%E5%BD%A2%E6%80%81%22%5D%0A%20%20Q%20--%3E%7C%E7%BC%BA%E6%AC%BE%E6%88%96%E5%A4%96%E6%B1%87%7C%20CSH%5B%22%E6%AC%BE%20fail%3A%20%E8%B7%A8%E5%A2%83%E4%B8%8E%E7%A1%AE%E8%AE%A4%E9%93%BE%E5%B8%B8%E8%A7%81%22%5D%0A%20%20SEC%20--%3E%20B%5B%22%E5%8D%96%E6%96%B9%E5%80%9F%E5%88%B8%E6%88%96%E8%A2%AB%E5%BC%BA%E5%88%B6%E8%A1%A5%E8%BF%9B%22%5D%0A%20%20CSH%20--%3E%20FI%5B%22%E8%9E%8D%E8%B5%84%E4%B8%8E%E5%A4%96%E6%B1%87%E7%AE%A1%E9%81%93%E8%A2%AB%E5%8E%8B%22%5D%0A%20%20B%20--%3E%20C%5B%22%E7%BD%9A%E9%87%91%E4%BD%8E%E4%BA%8E%E8%9E%8D%E8%B5%84%E6%94%B6%E7%9B%8A%E6%97%B6%2C%20fail%20%E8%A2%AB%E7%90%86%E6%80%A7%E7%BB%B4%E6%8C%81%22%5D%0A%20%20FI%20--%3E%20C%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p><span class="marginnote">中国结算对 A 股证券 T+1 交收、资金清算有自身时间表；不要把 DTCC 夜盘截止套过来。本课给的是状态机，时钟以各 CSD 公告为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>库存按交收日记账，同时保留成交日风险。营业日函数用结算日历，不是交易日历：债券假日、半日市、跨境节假日会使 \\(S(T)\\) 跳跃。机构交易的分配–确认–申认（ACA）在 T+1 制度下必须在成交日完成，见美国规则课。研究账户若拿不到确认时间戳，至少应用「未确认则 fail 概率升高」的情景，而不是 100% 夜盘成功。</p><p>度量：fail 率按名义、按券、按对手。与借券利率、特殊券（specialness）一起看：特殊券既贵又易 fail。策略容量在「可交收量」上估，不是在 ADV 上估——可借库存为零时，空头腿的 ADV 不相干。</p><p><span class="marginnote">数字实例：某券特殊期借券费 20%、fail 罚金年化约 3%。持有人把券锁在库里做回购能赚 6%，那么「不交收」每张券净赚 6%−3%=3%——这正是 Fleming–Garbade 说的「理性 fail」；后来的改革提高罚金，就是为了把这个差值打成负数。</span></p><h3 id="周期缩短是制度冲击-不是-alpha" tabindex="-1">周期缩短是制度冲击，不是 alpha <a class="header-anchor" href="#周期缩短是制度冲击-不是-alpha" aria-label="Permalink to &quot;周期缩短是制度冲击，不是 alpha&quot;">​</a></h3><p>T+1 改革对所有人同时生效，改变的是运营可行集。把「改革后隔夜异象变强」当因子，须先剔除 fail 与借券成本的机械通道。跨市场篮子按各市场自己的 \\(S(\\cdot)\\) 分别记账，避免用美国周期去推伦敦或香港腿。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>结算是 CSD 与支付系统上的交付对支付（DvP）或变体。CCP 净额减少交收笔数，但不消灭净额失败。失败使空头链延长：A 欠 B，B 欠 C，罚金与召回沿链传播。Garbade–Fleming 的价格含义是：fail 高时，特定券的融资与定价脱离一般抵押品利率。对股票多空，fail 表现为空头建立失败或多头晚到账，因子实现缺口增大。</p><p>与撮合的关系：引擎可以成交一张你交收不了的卖单（若前置检查未拦住）。前置检查（A 股前端、美股定位）试图把 fail 挡在撮合前；挡不住的进入本课。研究应声明模拟器实现了哪一层检查。</p>',10)),(l(),t(B,null,{default:e(()=>[A(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%88%90%E4%BA%A4%E6%97%A5%20T%22%5D%20--%3E%20ACA%5B%22%E5%8C%B9%E9%85%8D%E4%B8%8E%E7%A1%AE%E8%AE%A4%22%5D%0A%20%20ACA%20--%3E%20S%5B%22%E4%BA%A4%E6%94%B6%E6%97%A5%20S(T)%22%5D%0A%20%20S%20--%3E%20OK%5B%22DvP%20%E7%BB%88%E5%B1%80%22%5D%0A%20%20S%20--%3E%20Fail%5B%22%E5%A4%B1%E8%B4%A5%E4%BA%A4%E6%94%B6%22%5D%0A%20%20Fail%20--%3E%20Borrow%5B%22%E5%80%9F%E5%88%B8%E6%88%96%E8%9E%8D%E8%B5%84%22%5D%0A%20%20Fail%20--%3E%20Buyin%5B%22%E5%BC%BA%E5%88%B6%E8%A1%A5%E8%BF%9B%22%5D%0A%20%20Borrow%20--%3E%20S%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供故意 fail、滚动交收以占用对手券源的方案。罚金与强制补进规则以 CSD/CCP 现行办法为准。加密链上最终性、即时支付不在本课周期语言里。</p><p><span class="marginnote">常见误区：初学者容易把 fail 当成「极罕见的事故」。实际上在特殊券、公司行动日与跨境链上，fail 率可以到百分之几，且与你的空头腿集中在同一批名字上——平时看不见，紧张时和你最需要的券一起出现。这就是要把交收状态做成一等公民的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>成交、清算、结算是三态；fail 是 \\(S(T)\\) 上的合法状态，须进库存。</li><li>周期缩短压缩修复时间；券 fail 与款 fail 成本不同。</li><li>容量按可交收与可借，不按无约束 ADV。</li><li>出处：Fleming and Garbade, FRBNY, 2005；DTCC；SEC T+1 采用公告。</li></ul>',5))])}const D=n(d,[["render",f]]);export{c as __pageData,D as default};
